# Test xep loai QC 44 - mo phong logic frmSubjectMarkDetailOfCourse.FillData
# Chay: powershell -File Test_QC44_XepLoai.ps1

$BinhThuong = 0
$VanHoa = 1
$ChinhTri = 9

function Test-XepLoaiQC44 {
    param(
        [string]$StudentCode,
        [string]$StudentName,
        [int]$SoMonBinhThuongThiLai = 0,
        [string]$SanctionFormID = "",
        [array]$Subjects,
        [bool]$HaveNormalSubject = $true
    )

    Write-Host "========================================" -ForegroundColor Cyan
    Write-Host " TEST XEP LOAI QC 44 - $StudentCode" -ForegroundColor Cyan
    Write-Host " SV: $StudentName" -ForegroundColor Cyan
    Write-Host " SoMonBinhThuongThiLai: $SoMonBinhThuongThiLai | Ky luat: $(if($SanctionFormID){'Co'}else{'Khong'})" -ForegroundColor Cyan
    Write-Host "========================================" -ForegroundColor Cyan

    $dblTotalMark = 0.0
    $intUnitTextCount = 0
    $dblTotalMark_H4 = 0.0
    $intUnitTextCount_H4 = 0

    Write-Host ""
    Write-Host "Chi tiet mon tinh vao TBC:" -ForegroundColor Yellow
    Write-Host ("{0,-6} {1,-25} {2,4} {3,6} {4,6} {5,6} {6,8}" -f "Tinh?", "Mon", "TC", "TKM", "QDSo", "QDChu", "Ghi chu")
    Write-Host ("-" * 75)

    foreach ($s in $Subjects) {
        $included = $false
        $note = ""

        if ($s.IsIgnore) {
            $note = "Mien - bo qua"
        }
        elseif ($s.IsTextMark) {
            $note = "Diem chu - bo qua TBC"
        }
        else {
            $st = $s.SpecialType
            if (($HaveNormalSubject -and $st -eq $BinhThuong) `
                -or ((-not $HaveNormalSubject) -and $st -eq $VanHoa) `
                -or ($st -eq $ChinhTri)) {
                $included = $true
                if ($s.OtherFinalSummary -ne $null -and "$($s.OtherFinalSummary)" -ne "") {
                    $dblTotalMark_H4 += [double]$s.OtherFinalSummary * [int]$s.UnitText
                    $intUnitTextCount_H4 += [int]$s.UnitText
                }
                if ($s.FinalSummary -ne $null -and "$($s.FinalSummary)" -ne "") {
                    $dblTotalMark += [double]$s.FinalSummary * [int]$s.UnitText
                    $intUnitTextCount += [int]$s.UnitText
                }
            }
            else {
                $note = "Khong tinh (SpecialType=$st)"
            }
        }

        $flag = if ($included) { "X" } else { "" }
        $tkm = if ($null -ne $s.FinalSummary) { $s.FinalSummary } else { "" }
        $qds = if ($null -ne $s.OtherFinalSummary) { $s.OtherFinalSummary } else { "" }
        $qdc = if ($s.LearningLevel) { $s.LearningLevel } else { "" }
        Write-Host ("{0,-6} {1,-25} {2,4} {3,6} {4,6} {5,6} {6}" -f $flag, $s.SubjectName, $s.UnitText, $tkm, $qds, $qdc, $note)
    }

    if ($intUnitTextCount -le 0) {
        Write-Host ""
        Write-Host "Khong co mon nao tinh duoc TBC!" -ForegroundColor Red
        return
    }

    # Round giong C# MidpointRounding.AwayFromZero
    $tbc10 = [Math]::Round($dblTotalMark / $intUnitTextCount, 1, [MidpointRounding]::AwayFromZero)
    $tbc4 = 0.0
    if ($intUnitTextCount_H4 -gt 0) {
        $tbc4 = [double][decimal]::Round([decimal]($dblTotalMark_H4 / $intUnitTextCount_H4), 2, [MidpointRounding]::AwayFromZero)
    }

    Write-Host ""
    Write-Host "TONG KET:" -ForegroundColor Green
    Write-Host "  Tong diem H10 (co nhan TC): $dblTotalMark / $intUnitTextCount TC"
    Write-Host "  TBC He 10              : $tbc10"
    Write-Host "  Tong diem H4  (co nhan TC): $dblTotalMark_H4 / $intUnitTextCount_H4 TC"
    Write-Host "  TBC He 4               : $tbc4"

    # Xep loai QC 44 - theo TBC He 4
    $strLearningLevel = ""
    if ($tbc4 -ge 3.5) {
        if ($SoMonBinhThuongThiLai -gt 0 -or $SanctionFormID -ne "") {
            $strLearningLevel = "Gioi"
            $reason = "Ha bac XS -> Gioi (thi lai >=1 hoac ky luat)"
        }
        else {
            $strLearningLevel = "Xuat sac"
            $reason = "Dat nguong >= 3.5, khong bi ha bac"
        }
    }
    elseif ($tbc4 -ge 3.0) {
        if ($SoMonBinhThuongThiLai -gt 1 -or $SanctionFormID -ne "") {
            $strLearningLevel = "Kha"
            $reason = "Ha bac Gioi -> Kha (thi lai >1 hoac ky luat)"
        }
        else {
            $strLearningLevel = "Gioi"
            $reason = "Dat nguong >= 3.0"
        }
    }
    elseif ($tbc4 -ge 2.5) {
        $strLearningLevel = "Kha"
        $reason = "Dat nguong >= 2.5"
    }
    elseif ($tbc4 -ge 2.0) {
        $strLearningLevel = "Trung binh"
        $reason = "Dat nguong >= 2.0"
    }
    else {
        $strLearningLevel = "Yeu"
        $reason = "Duoi 2.0"
    }

    Write-Host ""
    Write-Host "XEP LOAI (QC 44, theo TBC He 4): $strLearningLevel" -ForegroundColor Magenta
    Write-Host "  Ly do: $reason" -ForegroundColor Magenta
    Write-Host ""
}

# ===== CASE 1: SV dat Xuat sac =====
Test-XepLoaiQC44 -StudentCode "SV001" -StudentName "Nguyen Van A" `
    -SoMonBinhThuongThiLai 0 -SanctionFormID "" `
    -Subjects @(
        @{ SubjectName="Toan"; UnitText=3; FinalSummary=8.5; OtherFinalSummary=3.5; LearningLevel="B"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="Ly";   UnitText=2; FinalSummary=9.0; OtherFinalSummary=4.0; LearningLevel="A"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="Hoa";  UnitText=2; FinalSummary=8.0; OtherFinalSummary=3.0; LearningLevel="B"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="GDCD"; UnitText=1; FinalSummary=7.5; OtherFinalSummary=2.5; LearningLevel="C"; SpecialType=$ChinhTri; IsIgnore=$false; IsTextMark=$false }
    )

# ===== CASE 2: Cung diem nhung bi ha bac vi thi lai 1 mon =====
Test-XepLoaiQC44 -StudentCode "SV002" -StudentName "Tran Thi B" `
    -SoMonBinhThuongThiLai 1 -SanctionFormID "" `
    -Subjects @(
        @{ SubjectName="Toan"; UnitText=3; FinalSummary=8.5; OtherFinalSummary=3.5; LearningLevel="B"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="Ly";   UnitText=2; FinalSummary=9.0; OtherFinalSummary=4.0; LearningLevel="A"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="Hoa";  UnitText=2; FinalSummary=8.0; OtherFinalSummary=3.0; LearningLevel="B"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
    )

# ===== CASE 3: TBC H4 >= 3.0 nhung thi lai > 1 mon -> Kha =====
Test-XepLoaiQC44 -StudentCode "SV003" -StudentName "Le Van C" `
    -SoMonBinhThuongThiLai 2 -SanctionFormID "" `
    -Subjects @(
        @{ SubjectName="Mon1"; UnitText=4; FinalSummary=7.0; OtherFinalSummary=2.5; LearningLevel="C"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="Mon2"; UnitText=4; FinalSummary=8.0; OtherFinalSummary=3.0; LearningLevel="B"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
        @{ SubjectName="Mon3"; UnitText=3; FinalSummary=8.5; OtherFinalSummary=3.5; LearningLevel="B"; SpecialType=$BinhThuong; IsIgnore=$false; IsTextMark=$false }
    )

