private void DebugTestXepLoaiOneStudent(long lngStudentID)
{
    if (dtbData == null || dtbClassSubject == null || dtbSubjectMark == null)
    {
        MessageManager.Warning("Chưa có dữ liệu. Bấm Tìm trước.");
        return;
    }

    DataRow drwStudent = null;
    foreach (DataRow drw in dtbData.Rows)
