        if (Convert.ToInt64(drw["StudentID"]) == lngStudentID)
        {
            drwStudent = drw;
            break;
        }
    }

    if (drwStudent == null)
    {
        MessageManager.Warning(String.Format("Không tìm thấy StudentID = {0} trong lớp đang chọn.", lngStudentID));
        return;
    }

    StringBuilder sb = new StringBuilder();
    sb.AppendLine(String.Format("=== TEST XẾP LOẠI QC {0} ===", intRegulationIDCurrent));
    sb.AppendLine(String.Format("StudentID : {0}", lngStudentID));
    sb.AppendLine(String.Format("Mã SV    : {0}", drwStudent["StudentCode"]));
    sb.AppendLine(String.Format("Họ tên   : {0} {1}", drwStudent["StudentFirstName"], drwStudent["StudentLastName"]));
    sb.AppendLine(String.Format("Thi lại  : {0} môn", drwStudent["SoMonBinhThuongThiLai"]));
    sb.AppendLine(String.Format("Kỷ luật  : {0}", drwStudent["SanctionFormID"].ToString() == "" ? "Không" : "Có"));
