    }

    sb.AppendLine("");
    sb.AppendLine(String.Format("TBC Hệ 10 : {0}", drwStudent["SummaryLearningMark"]));
    sb.AppendLine(String.Format("TBC Hệ 4  : {0}", drwStudent["OtherSummaryLearningMark"]));
    sb.AppendLine(String.Format("Xếp loại  : {0}", drwStudent["LearningLevel"]));
    sb.AppendLine("");
