        {
            gvData.FocusedRowHandle = i;
            gvData.SelectRow(i);
            break;
        }
    }

    MessageBox.Show(sb.ToString(), "Debug test xếp loại", MessageBoxButtons.OK, MessageBoxIcon.Information);
}

