        else
            sb.AppendLine(String.Format("He4={0} -> Yeu.", dblHe4));
    }
    else
    {
        sb.AppendLine(String.Format("QC {0}: xep loai theo TBC He 10 (= {1}), KHONG theo He 4.", intRegulationIDCurrent, dblHe10));
        if (dblHe10 >= 7 && dblHe10 < 8)
            sb.AppendLine("He 10 tu 7 den duoi 8 -> Kha (dung voi ket qua hien tai).");
    }

    return sb.ToString();
