/// <summary>
/// Môn nghề thi lại: SpecialType = BinhThuong và OrderLearning >= 2 (cùng tiêu chí SP đếm SoMonBinhThuongThiLai).
/// </summary>
private bool DebugIsMonBinhThuongThiLai(DataRow drwMark)
{
    if (Convert.ToBoolean(drwMark["IsIgnore"]))
        return false;
    if (Convert.ToInt32(drwMark["SpecialType"]) != Global.SubjectSpecialType.BinhThuong)
        return false;
    if (drwMark["OrderLearning"].ToString() == "")
        return false;
    return Convert.ToInt32(drwMark["OrderLearning"]) >= 2;
}

private string DebugGetSubjectDisplayCode(DataRow drwMark, DataRow drwSub)
{
    if (dtbSubjectMark.Columns.Contains("SubjectCode") && drwMark["SubjectCode"].ToString() != "")
        return drwMark["SubjectCode"].ToString();
    if (dtbClassSubject.Columns.Contains("SubjectCode") && drwSub["SubjectCode"].ToString() != "")
        return drwSub["SubjectCode"].ToString();
    if (drwSub["SubjectShortName"].ToString() != "")
        return drwSub["SubjectShortName"].ToString();
    return drwSub["SubjectName"].ToString();
}

/// <summary>
/// Liệt kê mã môn thi lại nghề cho popup debug.
/// </summary>
private string DebugGetMonThiLaiDetail(long lngStudentID, int intSoMonSP)
{
    StringBuilder sb = new StringBuilder();
    ArrayList arrMonThiLai = new ArrayList();
    DataRow[] rowsMark = dtbSubjectMark.Select("StudentID='" + lngStudentID.ToString() + "'");

    foreach (DataRow drwMark in rowsMark)
    {
        if (!DebugIsMonBinhThuongThiLai(drwMark))
            continue;

        string strSubjectID = drwMark["SubjectID"].ToString();
        DataRow[] rowSubjects = dtbClassSubject.Select("SubjectID='" + strSubjectID + "'");
        DataRow drwSub = rowSubjects.Length > 0 ? rowSubjects[0] : null;
        string strCode = drwSub != null ? DebugGetSubjectDisplayCode(drwMark, drwSub) : strSubjectID;
        string strName = drwSub != null ? drwSub["SubjectName"].ToString() : "";
        int intLan = Convert.ToInt32(drwMark["OrderLearning"]);
        arrMonThiLai.Add(String.Format("{0} ({1}) lan {2}", strCode, strName, intLan));
    }

    if (arrMonThiLai.Count == 0)
    {
        sb.AppendLine("  Danh sach mon thi lai: (khong tim thay OrderLearning>=2, mon nghề)");
    }
    else
    {
        sb.AppendLine(String.Format("  Danh sach mon thi lai ({0} mon):", arrMonThiLai.Count));
        for (int i = 0; i < arrMonThiLai.Count; i++)
            sb.AppendLine(String.Format("    {0}. {1}", i + 1, arrMonThiLai[i].ToString()));
    }

    if (arrMonThiLai.Count != intSoMonSP)
        sb.AppendLine(String.Format("  * Canh bao: SP dem {0} mon, quet du lieu {1} mon.", intSoMonSP, arrMonThiLai.Count));

    return sb.ToString();
}

